"//! op-vsctl — Native rovs-based ovs-vsctl replacement
//!
//! Provides a comprehensive CLI interface for OVSDB and OpenFlow operations
//! using pure Rust, memory-safe `rovs-*` crates. Introspects OVS commands
//! and translates them to native JSON-RPC transactions.

use anyhow::{bail, Context, Result};
use clap::{Parser, Subcommand};
use rovs_ovsdb::{Client, Transaction};
use serde_json::{json, Value};
use std::path::Path;
use std::time::Duration;
use tracing::{info, warn};
use tracing_subscriber::EnvFilter;
use uuid::Uuid;

#[derive(Parser)]
#[command(name = "op-vsctl", about = "Native rovs-based ovs-vsctl replacement", version)]
struct Cli {
    /// OVSDB socket path (auto-detected if omitted)
    #[arg(long)]
    db: Option<String>,

    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Create a new bridge
    AddBr {
        bridge: String,
        /// Datapath type (e.g., netdev, system)
        #[arg(long, default_value = "system")]
        datapath_type: String,
        /// Fail mode (standalone or secure)
        #[arg(long, default_value = "standalone")]
        fail_mode: String,
        /// Shared MAC address (useful for netdev bridges)
        #[arg(long)]
        mac: Option<String>,
    },
    /// Delete a bridge
    DelBr { bridge: String },
    /// Add a port to a bridge
    AddPort { bridge: String, port: String },
    /// Delete a port from a bridge
    DelPort { bridge: String, port: String },
    /// Set controller for a bridge
    SetController { bridge: String, target: String },
}

fn find_socket_path() -> String {
    let candidates = [
        "/usr/local/var/run/openvswitch/db.sock",
        "/run/openvswitch/db.sock",
        "/var/run/openvswitch/db.sock",
    ];
    candidates
        .iter()
        .find(|p| Path::new(p).exists())
        .unwrap_or(&"/usr/local/var/run/openvswitch/db.sock")
        .to_string()
}

