        fail_mode: String,
        /// Shared MAC address (useful for netdev bridges)
        #[arg(long)]
        mac: Option<String>,
    },
    /// Delete a bridge
    DelBr { bridge: String },
    /// Add a port to a bridge
    AddPort { bridge: String, port: String },
    /// Delete a port from a bridge
    DelPort { bridge: String, port: String },
    /// Set controller for a bridge
    SetController { bridge: String, target: String },
}

fn find_socket_path() -> String {
    let candidates = [
        "/usr/local/var/run/openvswitch/db.sock",
        "/run/openvswitch/db.sock",
        "/var/run/openvswitch/db.sock",
