se_syn_method(sig: &syn::Signature) -> Value {
+    let name = sig.ident.to_string();
+    let dbus_name = capitalize_first(&name);
+
+    let mut args = Vec::new();
+    for input in &sig.inputs {
+        if let syn::FnArg::Typed(pat_type) = input {
+            let arg_name = match &*pat_type.pat {
+                syn::Pat::Ident(ident) => ident.ident.to_string(),
+                _ => "arg".to_string(),
+            };
+            let ty_str = quote::quote!(#pat_type.ty).to_string();
+            args.push(json!({
+                "name": arg_name,
+                "type": map_rust_to_dbus_type(&ty_str),
+                "direction": "in"
+            }));
+        }
+    }
+
+    if let syn::ReturnType::Type(_, ty) = &sig.output {
+        let ty_str = quote::quote!(#ty).to_string();
+        args.push(json!({
+            "name": "result",
+            "type": map_rust_to_dbus_type(&ty_str),
+            "direction": "out"
+        }));
+    }
+
+    json!({
+        "name": dbus_name,
+        "args": args
+    })
+}
+
+fn capitalize_first(s: &str) -> String {
+    let mut c = s.chars();
+    match c.next() {
+        None => String::new(),
+        Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
+    }
+}
+
+fn map_rust_to_dbus_type(rust_ty: &str) -> String {
+    let ty = rust_ty.replace(" ", "");
+    if ty.contains("String") || ty.contains("&str") {
+        "s".to_string()
+    } else if ty.contains("u32") {
+        "u".to_string()
+    } else if ty.contains("i32") {
+        "i".to_string()
+    } else if ty.contains("bool") {
+        "b".to_string()
+    } else if ty.contains("f64") {
+        "d".to_string()
+    } else if ty.contains("Vec") || ty.contains("[]") {
+        "a".to_string() 
+    } else {
+        "s".to_string() 
+    }
+}

