/// Inspector Gadget Universal CLI
#[derive(Parser, Debug)]
#[command(author, version, about, long_about = None)]
struct Args {
    /// The parser adapter to use (e.g., auto, rust_crate, json, xml, binary)
    #[arg(short, long, default_value = "auto")]
    adapter: String,

    /// Optional flags to pass to the parser (comma-separated key=value pairs)
    #[arg(short, long)]
    flags: Option<String>,

    /// The file to inspect
    filename: PathBuf,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    tracing_subscriber::fmt::init();

    let args = Args::parse();

    let mut gadget = IntrospectiveGadget::new(Default::default()).await?;

    let code = fs::read_to_string(&args.filename).map_err(|e| {
        anyhow::anyhow!("Failed to read file {}: {}", args.filename.display(), e)
    })?;

    let mut metadata = HashMap::new();
    if let Some(flags_str) = args.flags {
        for pair in flags_str.split(',') {
            if let Some((k, v)) = pair.split_once('=') {
                metadata.insert(k.to_string(), serde_json::json!(v));
            } else {
                metadata.insert(pair.to_string(), serde_json::json!(true));
            }
        }
    }

    let input = InspectionInput {
        source: InspectionSource::RawData {
            format_hint: Some(args.adapter),
            description: args.filename.display().to_string(),
        },
        data: Some(code),
        metadata,
    };

    let result = gadget.parse(&input).await?;

    // Pretty print the JSON output from the parser
    println!("{}", serde_json::to_string_pretty(&result.data)?);

    Ok(())
}"

