"use anyhow::{Context, Result};
use rovs_openflow::{Address, Flow, VConn};
use std::sync::Arc;
use tokio::sync::Mutex;
use zbus::{connection::Builder, interface};
use tracing::{info, warn, error};

struct OpenFlowServer {
    /// Holds an optional connection to the OpenFlow switch.
    /// In a real implementation, this might manage multiple VConns.
    vconn: Arc<Mutex<Option<VConn>>>,
}

#[interface(name = "org.op_dbus.OpenFlowInterface")]
impl OpenFlowServer {
    /// Connect to the OpenFlow switch
    async fn connect(&self, addr: String) -> zbus::fdo::Result<String> {
        let parsed_addr = addr.parse::<Address>().map_err(|e| {
            zbus::fdo::Error::InvalidArgs(format!("Invalid OpenFlow Address: {}", e))
        })?;

        let mut vconn_guard = self.vconn.lock().await;

        match VConn::connect(&parsed_addr).await {
            Ok(new_vconn) => {
                *vconn_guard = Some(new_vconn);
                Ok(format!("Connected to OpenFlow switch at {}", addr))
            }
            Err(e) => Err(zbus::fdo::Error::Failed(format!("Failed to connect: {}", e))),
        }
    }

    /// Send a flow modification
    async fn send_flow(&self, flow_json: String) -> zbus::fdo::Result<String> {
