"/// Walks the Clap Command tree and converts it to a D-Bus compatible XML introspection format
fn generate_dbus_introspection(cmd: &clap::Command) -> String {
    let mut xml = String::new();
    xml.push_str("<!DOCTYPE node PUBLIC \"-//freedesktop//DTD D-BUS Object Introspection 1.0//EN\"\n");
    xml.push_str(" \"http://www.freedesktop.org/standards/dbus/1.0/introspect.dtd\">\n");
    xml.push_str("<node>\n");
    xml.push_str(&format!("  <interface name=\"org.op_dbus.{}\">\n", cmd.get_name().replace("-", "_")));

    for subcmd in cmd.get_subcommands() {
        if subcmd.get_name() == "help" || subcmd.get_name() == "introspect" {
            continue;
        }

        // Convert CLI subcommand name (e.g. add-br) to D-Bus method name (e.g. AddBr)
        let method_name: String = subcmd.get_name()
            .split('-')
            .map(|s| {
                let mut c = s.chars();
                match c.next() {
                    None => String::new(),
                    Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
                }
            })
            .collect();

        xml.push_str(&format!("    <method name=\"{}\">\n", method_name));

        // Map arguments to D-Bus input signatures
        for arg in subcmd.get_arguments() {
            if arg.get_id().as_str() == "help" || arg.get_id().as_str() == "version" {
                continue;
            }

            // Assume string ('s') for basic CLI args
            xml.push_str(&format!("      <arg name=\"{}\" type=\"s\" direction=\"in\"/>\n", arg.get_id().as_str()));
        }

        xml.push_str("    </method>\n");
    }

    xml.push_str("  </interface>\n</node>");
    xml
}"

