"use anyhow::Result;
use op_network::openflow::FlowEntry;
use std::error::Error;
use zbus::{connection::Builder, interface};

struct OpenvSwitchCommands;

#[interface(name = "org.opdbus.OpenvSwitchCommands")]
impl OpenvSwitchCommands {
    /// Add a flow to a bridge
    async fn add_flow(&self, _bridge: &str, _flow_json: &str) -> zbus::fdo::Result<bool> {
        // Here we will eventually deserialize FlowEntry and call OpenFlowClient
        // For now, this is a native DBus interface stub.
        Ok(true)
    }

    /// Delete all flows
    async fn delete_all_flows(&self, _bridge: &str) -> zbus::fdo::Result<bool> {
        Ok(true)
    }

    /// Dump flows
    async fn dump_flows(&self, _bridge: &str) -> zbus::fdo::Result<Vec<String>> {
        Ok(vec![])
    }

    // Additional methods will be implemented natively using rovs_openflow and rovs_vsctl
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn Error>> {
    env_logger::init();

    let daemon = OpenvSwitchCommands;
    let _conn = Builder::system()?
        .name("org.opdbus.OpenvSwitchCommands")?
        .serve_at("/org/opdbus/OpenvSwitchCommands", daemon)?
        .build()
        .await?;

    log::info!("op-openvswitch-daemon running on system bus at org.opdbus.OpenvSwitchCommands");

    // Run forever
    std::future::pending::<()>().await;

    Ok(())
}
"

"use zbus::proxy;

/// Proxy trait for the org.opdbus.OpenvSwitchCommands D-Bus interface.
/// This allows op-plugins and other components to easily call OVS commands over D-Bus
/// without needing to implement the raw JSON-RPC or OpenFlow sockets themselves.
#[proxy(
    interface = "org.opdbus.OpenvSwitchCommands",
    default_service = "org.opdbus.OpenvSwitchCommands",
    default_path = "/org/opdbus/OpenvSwitchCommands"
)]
pub trait OpenvSwitchCommands {
    /// Add a flow to a bridge
    async fn add_flow(&self, bridge: &str, flow_json: &str) -> zbus::Result<bool>;

    /// Delete all flows
    async fn delete_all_flows(&self, bridge: &str) -> zbus::Result<bool>;

    /// Dump flows
    async fn dump_flows(&self, bridge: &str) -> zbus::Result<Vec<String>>;
}
"

